  input wire i_ebreak,
  input wire i_mem_cmd,
  input wire i_mstatus_en,
  input wire i_mie_en,
  input wire i_mcause_en,
  input wire i_mret,
  input wire i_csr_d_sel,
  input wire [1:0] i_csr_source,
  input wire [B:0] i_rf_csr_out,
  input wire [B:0] i_csr_imm,
  input wire [B:0] i_rs1,
  output reg o_new_irq,
  output wire [B:0] o_csr_in,
  output wire [B:0] o_q
);

  reg MIE;
  reg MPIE;
  reg MTIE;
  reg cause_irq;
  reg [3:0] cause_code;
  reg irq_q;
  wire timer_irq;assign timer_irq = i_mtip & MIE & MTIE;
  wire [B:0] d;assign d = (i_csr_d_sel)? i_csr_imm : i_rs1;
  reg [B:0] status_view;
  reg [B:0] cause_view;

  always @(*) begin
    if(W == 1) status_view = MIE & i_cnt3 | i_cnt11 | i_cnt12; 
    else status_view = { i_cnt11 | MIE & i_cnt3, 2'b00, i_cnt12 };
  end


  always @(*) begin
    cause_view = { B + 1{ 1'b0 } };
    if(i_cnt0to3) cause_view = cause_code[B:0]; 
    else if(i_cnt_done) cause_view[B] = cause_irq; 
  end

  wire g_st;assign g_st = i_mstatus_en & i_en;
  wire g_ca;assign g_ca = i_mcause_en & i_en;
  wire [B:0] csr_out;assign csr_out = i_rf_csr_out | { B + 1{ g_st } } & status_view | { B + 1{ g_ca } } & cause_view;
  assign o_q = csr_out;
  assign o_csr_in = (i_csr_source == 2'b00)? csr_out : 
                    (i_csr_source == 2'b01)? d : 
                    (i_csr_source == 2'b10)? csr_out | d : csr_out & ~d;
  wire X2;
  wire X1;
  wire X0;

  generate if(W == 1) begin : g_w1
    assign X2 = cause_code[3];
    assign X1 = cause_code[2];
    assign X0 = cause_code[1];
  end else begin : g_w4
    assign X2 = o_csr_in[2];
    assign X1 = o_csr_in[1];
    assign X0 = o_csr_in[0];
  end
  endgenerate

  wire cause_en;assign cause_en = i_mcause_en & i_en & i_cnt0to3 | i_trap & i_cnt_done;
  wire b3;assign b3 = i_e_op & ~i_ebreak | ~i_trap & o_csr_in[B];
  wire b2;assign b2 = o_new_irq | i_mem_op | ~i_trap & X2;
  wire b1;assign b1 = o_new_irq | i_e_op | i_mem_op & i_mem_cmd | ~i_trap & X1;
  wire b0;assign b0 = o_new_irq | i_e_op | ~i_trap & X0;

  always @(posedge i_clk) begin
    if(i_trig_irq) begin
      irq_q <= timer_irq;
      o_new_irq <= timer_irq & ~irq_q;
    end 
