  end


  always @(posedge i_clk) begin
    if(i_mie_en & i_cnt7) MTIE <= o_csr_in[B]; 
  end


  always @(posedge i_clk) begin
    if(i_trap & i_cnt_done | i_mstatus_en & i_cnt3 & i_en | i_mret) begin
      if(i_trap) MIE <= 1'b0; 
      else if(i_mret) MIE <= MPIE; 
      else MIE <= o_csr_in[B];
    end 
  end


  always @(posedge i_clk) begin
    if(i_trap & i_cnt_done) MPIE <= MIE; 
  end


  always @(posedge i_clk) begin
    if(cause_en) cause_code <= { b3, b2, b1, b0 }; 
