  input wire clk,
  input wire areset,
  input wire x,
  output reg z
);


  always @(posedge clk or posedge areset) begin
    if(areset) z <= 1'b0; 
    else if(x) z <= 1'b1; 
    else z <= z;
  end


endmodule

